-- Visual boxes/tables use CSS variables so they adapt to light/dark mode.

-- 1 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/how-to-prepare-canadian-citizenship-test-2026.svg',
short_description='Learn how to prepare for the Canadian citizenship test in 2026 with a clear study plan, practice questions, mock tests, and proven tips.',
content='<p>Preparing for the Canadian citizenship test in 2026 is much easier when you follow a clear plan. The test is based on the official <strong>Discover Canada</strong> study guide, and almost everyone who studies properly passes on their first try. This guide walks you through exactly how to prepare, step by step.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0 0 8px;font-weight:700">The test at a glance</p><ul style="margin:0"><li><strong>Questions:</strong> 20 (multiple choice and true/false)</li><li><strong>Time limit:</strong> 45 minutes</li><li><strong>Pass mark:</strong> 15 out of 20 (75%)</li><li><strong>Language:</strong> English or French</li><li><strong>Based on:</strong> the Discover Canada study guide</li></ul></div><h2>Step 1: Understand what the test covers</h2><p>The test draws from across Discover Canada, including Canada’s history, geography, system of government, laws, economy, national symbols, and the rights and responsibilities of citizenship. Knowing the map of topics makes the details easier to absorb.</p><h2>Step 2: Build a simple study plan</h2><p>Instead of cramming, study one topic at a time over a week or two. A realistic plan looks like this:</p><table style="width:100%;border-collapse:collapse;margin:20px 0"><thead><tr><th style="text-align:left;border-bottom:2px solid var(--color-border);padding:8px">Day</th><th style="text-align:left;border-bottom:2px solid var(--color-border);padding:8px">Focus</th></tr></thead><tbody><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Day 1</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Rights and responsibilities</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Day 2</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Canadian history</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Day 3</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Government and elections</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Day 4</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Geography and regions</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Day 5</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Symbols, economy, and review</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Day 6</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Practice questions by topic</td></tr><tr><td style="padding:8px">Day 7</td><td style="padding:8px">Full 20-question mock test and review</td></tr></tbody></table><h2>Step 3: Practise with questions and mock tests</h2><p>Reading alone is not enough. After each topic, answer practice questions to see what you actually remember. Once you finish the guide, take full mock tests that match the real format: 20 questions in 45 minutes. Aim to score 18 or higher before your real exam so you have a comfortable margin.</p><h2>Step 4: Use tips that make studying stick</h2><ul><li>Study a little every day rather than in long, rare sessions.</li><li>Use the audio version of Discover Canada if reading is hard.</li><li>Keep a list of questions you get wrong and revisit them.</li><li>Focus on understanding ideas, not just memorizing facts.</li></ul><h2>Common pitfalls to avoid</h2><p>Do not wait until the last minute, do not skip topics you find boring, and do not rely only on practice questions without reading the official guide. Slow, steady preparation beats last-minute cramming every time.</p><p>With a clear plan and regular practice, you can walk into your 2026 citizenship test calm and confident.</p><p><strong>Ready to practise?</strong> <a href="/practice/">Use a Canadian citizenship practice test app</a> to study faster, track your progress, and practise anytime.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='how-to-prepare-canadian-citizenship-test-2026';

-- 2 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/what-is-on-the-canadian-citizenship-test.svg',
short_description='A clear breakdown of what is on the Canadian citizenship test: every topic, the format, the number of questions, and the passing score.',
content='<p>If you want to know exactly <strong>what is on the Canadian citizenship test</strong>, this guide breaks it down topic by topic. The test checks your knowledge of Canada and what it means to be a citizen, and every question is based on the official Discover Canada study guide.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0 0 8px;font-weight:700">The test at a glance</p><ul style="margin:0"><li><strong>Questions:</strong> 20 (multiple choice and true/false)</li><li><strong>Time limit:</strong> 45 minutes</li><li><strong>Pass mark:</strong> 15 out of 20 (75%)</li><li><strong>Language:</strong> English or French</li></ul></div><h2>The topics you will be tested on</h2><table style="width:100%;border-collapse:collapse;margin:20px 0"><thead><tr><th style="text-align:left;border-bottom:2px solid var(--color-border);padding:8px">Topic</th><th style="text-align:left;border-bottom:2px solid var(--color-border);padding:8px">Examples of what to know</th></tr></thead><tbody><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">History</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Indigenous peoples, Confederation, the World Wars</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Government</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Parliament, the Prime Minister, how laws are made</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Rights &amp; responsibilities</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Voting, obeying the law, serving on a jury</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Geography</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Provinces, territories, capitals, regions</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px">Symbols</td><td style="border-bottom:1px solid var(--color-border);padding:8px">The flag, the anthem, national symbols</td></tr><tr><td style="padding:8px">Economy</td><td style="padding:8px">Major industries and trading partners</td></tr></tbody></table><h2>What the test does not check</h2><p>The test does not directly measure your English or French speaking ability. However, you do need to understand the questions in one of the two official languages to answer them correctly.</p><h2>How to prepare for these topics</h2><p>Read the official guide one chapter at a time, then test yourself with practice questions on that chapter. This shows you which topics need more review and helps you remember the facts that matter most.</p><p><strong>Tip:</strong> <a href="/practice/">A citizenship test app</a> can help you study each topic and practise test-style questions before the real exam.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='what-is-on-the-canadian-citizenship-test';

-- 3 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/canadian-citizenship-test-practice-questions.svg',
short_description='Learn what Canadian citizenship test practice questions look like, see examples, and discover how to use them to prepare effectively.',
content='<p>Practice questions are one of the most powerful tools for passing the Canadian citizenship test. They show you the style of the real questions, reveal your weak spots, and build the confidence you need on exam day. Here is what to expect and how to use them well.</p><h2>What practice questions look like</h2><p>The real test uses multiple-choice and true/false questions, so good practice questions follow the same format. They cover history, government, rights and responsibilities, symbols, geography, and laws.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0 0 6px;font-weight:700">Example question</p><p style="margin:0 0 6px">Which document protects the rights and freedoms of people in Canada?</p><ul style="margin:0"><li>A. The Discover Canada guide</li><li>B. The Canadian Charter of Rights and Freedoms</li><li>C. The Constitution of the United States</li></ul><p style="margin:8px 0 0"><strong>Answer:</strong> B — the Canadian Charter of Rights and Freedoms.</p></div><h2>How to use practice questions effectively</h2><ol><li>Read one chapter of Discover Canada.</li><li>Answer practice questions for that chapter.</li><li>Review every question you got wrong and re-read that part of the guide.</li><li>Repeat until you are scoring consistently high.</li></ol><h2>Practice questions are not a replacement for the guide</h2><p>The Government of Canada says all official questions are based on Discover Canada, so the guide should always be your main resource. Use practice questions to test and reinforce what you read, not to replace it.</p><h2>Finish with full mock tests</h2><p>Before your real exam, take several full mock tests of 20 questions in 45 minutes. This is the best way to know whether you are truly ready.</p><p><strong>Practise daily:</strong> <a href="/practice/">Use a Canadian citizenship practice test app</a> to answer questions every day and build confidence before exam day.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='canadian-citizenship-test-practice-questions';

-- 4 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/how-hard-is-the-canadian-citizenship-test.svg',
short_description='Is the Canadian citizenship test hard? Here is an honest look at the difficulty, what trips people up, and how to make it easy.',
content='<p>One of the most common worries from applicants is <strong>how hard is the Canadian citizenship test</strong>. The honest answer: it is very manageable with preparation. Most people who study the official guide and practise regularly pass on their first try.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0 0 8px;font-weight:700">The test at a glance</p><ul style="margin:0"><li><strong>Questions:</strong> 20 (multiple choice and true/false)</li><li><strong>Time limit:</strong> 45 minutes</li><li><strong>Pass mark:</strong> 15 out of 20 (75%)</li></ul></div><h2>What makes it feel hard</h2><p>The challenge is not the question style, which is straightforward. It is the amount of detail. Specific dates, names, and government roles can feel like a lot to remember at first. The topics that most often trip people up include:</p><ul><li>Specific dates in Canadian history</li><li>The roles of government officials</li><li>The rights and responsibilities of citizenship</li><li>Provincial and territorial capitals</li></ul><h2>Why most people pass</h2><p>Difficulty depends almost entirely on preparation. With 45 minutes for 20 questions, you have more than two minutes per question, so time pressure is rarely the problem. Applicants who read Discover Canada and take practice tests usually find the real exam comfortable.</p><h2>How to make it easy</h2><p>Study in small sections instead of all at once. Take notes, use the audio version if it helps, and test yourself with practice questions. Understand the ideas behind the facts: when you know how Canada’s government works or why citizenship responsibilities matter, the questions almost answer themselves.</p><p>Aim to score 18 or more on practice tests before your exam, and the real test will feel easy.</p><p><strong>Make it less stressful:</strong> <a href="/practice/">A citizenship test app</a> can give you quizzes, mock tests, and topic-by-topic practice.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='how-hard-is-the-canadian-citizenship-test';

-- 5 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/study-discover-canada.svg',
short_description='A practical guide to the Discover Canada study guide: what to focus on, how to study it chapter by chapter, and how to remember more.',
content='<p>The <strong>Discover Canada</strong> study guide is the official resource for the Canadian citizenship test, and every official question is based on it. Learning how to study it well is the single most important thing you can do to pass.</p><h2>What Discover Canada covers</h2><p>The guide includes the rights and responsibilities of citizenship, Canadian history, modern Canada, the system of government, federal elections, the justice system, national symbols, the economy, and the regions of Canada.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0 0 8px;font-weight:700">Focus your attention on</p><ul style="margin:0"><li>Key people and dates</li><li>Government roles and how laws are made</li><li>Rights and responsibilities of citizens</li><li>Provinces, territories, and their capitals</li><li>National symbols</li></ul></div><h2>Study it chapter by chapter</h2><p>Do not try to memorize every sentence. Read one chapter, then answer practice questions on it before moving on. Review anything you get wrong by going back to that chapter. This read-test-review loop is far more effective than reading alone.</p><h2>Use the format that works for you</h2><p>Discover Canada is available to read online, download, or listen to as audio. If reading is difficult, listen to the audio while following the text. This is especially helpful if English or French is not your first language.</p><h2>Combine the guide with practice</h2><p>Third-party practice tests are useful for checking your memory, but Discover Canada should always be your main source. Use the two together: read the guide, then test yourself.</p><p><strong>Study smarter:</strong> <a href="/practice/">Use a citizenship test app</a> alongside Discover Canada to review each topic and practise with mock questions.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='study-discover-canada';

-- 6 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/best-way-to-study-canadian-citizenship-test.svg',
short_description='The best way to study for the Canadian citizenship test combines reading, listening, practising, and reviewing. Here is how to do it.',
content='<p>The <strong>best way to study for the Canadian citizenship test</strong> is to combine four methods: reading, listening, practising, and reviewing. Relying on just one is rarely enough. Here is a complete approach that works.</p><h2>1. Read the official guide</h2><p>Start with Discover Canada. Read one section at a time and highlight important facts about Canada’s history, government, rights, responsibilities, symbols, geography, and regions.</p><h2>2. Practise with questions</h2><p>After each section, answer practice questions to check your memory. When you get something wrong, return to the guide and review it. This is far more effective than memorizing the correct answer alone.</p><h2>3. Listen to audio lessons</h2><p>Listening to the guide while reading improves understanding and retention, especially if English or French is not your first language. Audio also lets you study while commuting or doing chores.</p><h2>4. Take full mock tests</h2><p>Once you have covered every topic, take mock tests of 20 questions in 45 minutes, just like the real exam. They build confidence and improve your timing.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0 0 8px;font-weight:700">A balanced weekly routine</p><ul style="margin:0"><li><strong>Most days:</strong> read one topic + a short quiz</li><li><strong>Midweek:</strong> listen to the audio version to review</li><li><strong>Weekend:</strong> one full mock test, then review mistakes</li></ul></div><p>Study a little every day instead of cramming. Daily practice is more effective and far less stressful.</p><p><strong>Build a routine:</strong> <a href="/practice/">A Canadian citizenship test app</a> can help you create a daily study routine and practise wherever you are.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='best-way-to-study-canadian-citizenship-test';

-- 7 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/canadian-citizenship-test-history-government-rights.svg',
short_description='A deep dive into the four biggest citizenship test topics: Canadian history, government, rights, and responsibilities.',
content='<p>The Canadian citizenship test covers many topics, but four areas come up again and again: history, government, rights, and responsibilities. Master these and you cover most of the exam.</p><h2>Canadian history</h2><p>History questions span the Indigenous peoples, European settlement, Confederation in 1867, Canada’s role in the World Wars, and the development of modern Canada. Focus on major events and why they matter, not just dates in isolation.</p><h2>Government</h2><p>Government questions cover Parliament, the Prime Minister, the Governor General, elections, political parties, and the three levels of government. Know how Canadians choose their representatives and how a bill becomes law.</p><h2>Rights</h2><p>Citizens and residents in Canada enjoy several categories of rights:</p><ul><li>Democratic rights, such as the right to vote</li><li>Mobility rights, such as living and working anywhere in Canada</li><li>Legal rights</li><li>Equality rights</li><li>Fundamental freedoms, including religion, speech, assembly, and association</li></ul><h2>Responsibilities</h2><p>Rights come with responsibilities. Citizens are expected to obey the law, vote in elections, serve on a jury when called, help others in the community, and protect Canada’s heritage and environment.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0;font-weight:700">Study tip</p><p style="margin:6px 0 0">These four topics are large, so study them one at a time and quiz yourself after each. Understanding the reasons behind rights and responsibilities makes the questions much easier.</p></div><p><strong>Review by topic:</strong> <a href="/practice/">Use a citizenship test practice app</a> to review history, government, rights, and responsibilities with topic-based quizzes.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='canadian-citizenship-test-history-government-rights';

-- 8 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/how-many-questions-canadian-citizenship-test.svg',
short_description='The Canadian citizenship test has 20 questions and you have 45 minutes. Here is the full format, pass mark, and timing explained.',
content='<p>A very common question from applicants is <strong>how many questions are on the Canadian citizenship test</strong>. The answer is simple, and understanding the full format helps you prepare with confidence.</p><h2>The short answer</h2><p>The test has <strong>20 questions</strong>, and you need <strong>15 correct</strong> to pass — a score of 75%.</p><h2>The full format</h2><table style="width:100%;border-collapse:collapse;margin:20px 0"><tbody><tr><td style="border-bottom:1px solid var(--color-border);padding:8px;font-weight:600">Number of questions</td><td style="border-bottom:1px solid var(--color-border);padding:8px">20</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px;font-weight:600">Question types</td><td style="border-bottom:1px solid var(--color-border);padding:8px">Multiple choice and true/false</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px;font-weight:600">Time limit</td><td style="border-bottom:1px solid var(--color-border);padding:8px">45 minutes</td></tr><tr><td style="border-bottom:1px solid var(--color-border);padding:8px;font-weight:600">Pass mark</td><td style="border-bottom:1px solid var(--color-border);padding:8px">15 out of 20 (75%)</td></tr><tr><td style="padding:8px;font-weight:600">Source material</td><td style="padding:8px">The Discover Canada study guide</td></tr></tbody></table><h2>How much time per question?</h2><p>With 45 minutes for 20 questions, you have more than two minutes each — plenty of time if you have studied. Most well-prepared applicants finish with time to spare.</p><h2>Why every question matters</h2><p>Because there are only 20 questions, you can miss at most five and still pass. That is why steady preparation matters. The best way to get ready is to study the official guide and take full mock tests that mirror the real format.</p><p>If you are scoring 15 or higher on practice tests, you are making good progress. If not, review your weak areas and keep practising.</p><p><strong>Practise the format:</strong> <a href="/practice/">A citizenship test app</a> can help you take unlimited mock tests and improve your score before the real exam.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='how-many-questions-canadian-citizenship-test';

-- 9 -------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/canadian-citizenship-test-mistakes-to-avoid.svg',
short_description='Avoid the most common Canadian citizenship test mistakes, from skipping the official guide to ignoring your wrong answers.',
content='<p>Many applicants make the same avoidable mistakes when preparing for the Canadian citizenship test. Steer clear of these and you greatly improve your chances of passing on the first try.</p><h2>Mistake 1: Skipping the official guide</h2><p>Practice questions are useful, but the real test is based on Discover Canada. Always make the official guide your main resource.</p><h2>Mistake 2: Leaving studying to the last minute</h2><p>The guide covers many topics. Cramming the night before rarely works. Start early and study a little each day.</p><h2>Mistake 3: Only memorizing answers</h2><p>Real questions are often worded differently from practice questions. If you understand the topic, you can answer any version of the question. Memorizing a single phrasing is risky.</p><h2>Mistake 4: Ignoring difficult sections</h2><p>Some people skip government, elections, or history because they find them dull. These topics are important and frequently appear on the test.</p><h2>Mistake 5: Not reviewing wrong answers</h2><p>Your mistakes are your study guide. Each wrong answer shows you exactly what to review next.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0;font-weight:700">The fix in one line</p><p style="margin:6px 0 0">Read the official guide, start early, understand (do not just memorize), cover every topic, and review your mistakes.</p></div><p>Prepare calmly, practise regularly, and focus on understanding the material.</p><p><strong>Track your weak spots:</strong> <a href="/practice/">Use a citizenship practice test app</a> to track wrong answers and review the topics that need more attention.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='canadian-citizenship-test-mistakes-to-avoid';

-- 10 ------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/how-to-pass-canadian-citizenship-test-first-try.svg',
short_description='A step-by-step plan to pass the Canadian citizenship test on your first try, with study tips, mock test strategies, and test-day advice.',
content='<p>Passing the Canadian citizenship test on your first try is very achievable with the right preparation. Follow this step-by-step plan and you will walk in ready.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0 0 8px;font-weight:700">The test at a glance</p><ul style="margin:0"><li><strong>Questions:</strong> 20 — you need 15 correct to pass</li><li><strong>Time limit:</strong> 45 minutes</li><li><strong>Based on:</strong> the Discover Canada study guide</li></ul></div><h2>1. Read the official guide carefully</h2><p>Everything on the test comes from Discover Canada, so start there. Read it thoroughly rather than skimming.</p><h2>2. Make a simple schedule</h2><p>Study one topic at a time instead of everything in one day. Cover history, government, geography, rights, responsibilities, symbols, and laws across several short sessions.</p><h2>3. Test yourself after each topic</h2><p>Answer practice questions after reading. They lock in the facts and show you where you need more review.</p><h2>4. Take full mock tests</h2><p>Practise with 20-question mock tests timed to 45 minutes. They build confidence and sharpen your timing. Aim to score 18 or higher before your real exam.</p><h2>5. Review your wrong answers</h2><p>Do not just note the correct option — go back to the guide and understand why it is right.</p><h2>6. Stay calm on test day</h2><p>Read each question slowly and do not rush. With more than two minutes per question, you have time to think. If you studied regularly, you are ready.</p><p><strong>Get exam-ready:</strong> <a href="/practice/">A Canadian citizenship test app</a> can help you prepare with practice questions, mock tests, audio lessons, and progress tracking.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='how-to-pass-canadian-citizenship-test-first-try';

-- 11 ------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/top-10-tips.svg',
short_description='Ten practical, proven tips to help you study smarter and pass the Canadian citizenship test on your first try.',
content='<p>Preparing for the Canadian citizenship test does not have to be stressful. With the right approach, most people pass on their first attempt. Here are ten practical tips to help you get there.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0 0 8px;font-weight:700">The test at a glance</p><ul style="margin:0"><li><strong>Questions:</strong> 20 — you need 15 to pass</li><li><strong>Time limit:</strong> 45 minutes</li><li><strong>Based on:</strong> the Discover Canada study guide</li></ul></div><h2>1. Study the official guide first</h2><p>Every question comes from Discover Canada. Read it before anything else.</p><h2>2. Practise with realistic mock exams</h2><p>Timed practice tests are the fastest way to find weak spots. Match the real 20-question, 45-minute format.</p><h2>3. Focus on rights and responsibilities</h2><p>These come up often, so know them well.</p><h2>4. Learn key dates and events</h2><p>Confederation in 1867, the World Wars, and major milestones are common topics.</p><h2>5. Know your government</h2><p>Understand the monarch, the Governor General, the Prime Minister, and your Member of Parliament.</p><h2>6. Study a little every day</h2><p>Short daily sessions beat last-minute cramming. Aim for 20 to 30 minutes a day.</p><h2>7. Use your province information</h2><p>Some questions relate to where you live, including your provincial capital and representatives.</p><h2>8. Review questions you get wrong</h2><p>Keep a list of mistakes and revisit them until they stick.</p><h2>9. Stay calm on test day</h2><p>You need 15 out of 20 to pass. Read each question carefully and do not rush.</p><h2>10. Practise in your preferred language</h2><p>If English or French is not your first language, study key terms in your own language first to build understanding.</p><p><strong>Ready to practise?</strong> <a href="/practice/">Try a free mock exam</a> and track your progress as you study.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='top-10-tips';

-- 12 ------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/success-story-pr-to-citizen.svg',
short_description='A realistic look at the journey from permanent resident to Canadian citizen, including how to prepare for the knowledge test.',
content='<p>Becoming a Canadian citizen is a milestone worth celebrating. Every journey is different, but the path from permanent resident to citizen usually follows a familiar set of steps. Here is what to expect.</p><h2>Step 1: Meet the eligibility requirements</h2><p>You generally need to have been a permanent resident and physically present in Canada for a required number of days, and to meet tax and language requirements. Rules can change, so always confirm the current requirements on canada.ca.</p><h2>Step 2: Submit your application</h2><p>Once eligible, you submit your citizenship application with the supporting documents.</p><h2>Step 3: Prepare for the citizenship test</h2><p>If you are within the required age range, you will take the citizenship knowledge test. This is the step you can fully control through preparation. Study Discover Canada and take practice exams until you are consistently scoring above the pass mark.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0;font-weight:700">The test in brief</p><p style="margin:6px 0 0">20 questions, 45 minutes, and you need 15 correct to pass. It is based entirely on the Discover Canada guide.</p></div><h2>Step 4: Attend the ceremony</h2><p>After passing, the final step is the citizenship ceremony, where you take the Oath of Citizenship and officially become Canadian.</p><p>The knowledge test is the part you can prepare for with certainty. Start early, practise often, and the rest of the journey becomes much less stressful.</p><p><strong>Start preparing:</strong> <a href="/practice/">Use a citizenship test app</a> to study and practise for the knowledge test.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='success-story-pr-to-citizen';

-- 13 ------------------------------------------------------------------
UPDATE `blogs` SET image='/blog/what-to-study-canadian-citizenship-test.svg',
short_description='A complete checklist of what to study for the Canadian citizenship test, organized by topic so nothing slips through the cracks.',
content='<p>Knowing <strong>what to study for the Canadian citizenship test</strong> saves time and stress. Everything on the test comes from Discover Canada, so use this checklist to make sure you cover every key area.</p><h2>1. Rights and responsibilities</h2><p>Understand the rights of citizens and the responsibilities that come with citizenship. This is one of the most heavily tested topics.</p><h2>2. Canadian history</h2><p>Focus on key milestones: Indigenous peoples, early settlement, Confederation in 1867, the World Wars, and modern Canada.</p><h2>3. How government works</h2><p>Learn the three levels of government, the roles of the monarch, Governor General, Prime Minister, and Members of Parliament, and how laws are made.</p><h2>4. Voting and elections</h2><p>Know how federal elections work and the responsibilities of voters.</p><h2>5. Geography</h2><p>Study the provinces and territories, their capitals, and Canada’s major regions.</p><h2>6. National symbols and identity</h2><p>Be familiar with the flag, the anthem, important symbols, and notable Canadians.</p><h2>7. Your province or territory</h2><p>Some questions relate to where you live, including local representatives and your provincial capital.</p><div style="background:var(--color-surface-2);border:1px solid var(--color-border);border-left:4px solid var(--color-accent);padding:14px 20px;border-radius:8px;margin:24px 0"><p style="margin:0;font-weight:700">Final step</p><p style="margin:6px 0 0">Once you have covered every topic, take full-length practice tests. Review any topic where you score low and test again until you are consistently passing.</p></div><p><strong>Study by topic:</strong> <a href="/practice/">Use a citizenship test app</a> to work through each area and take practice tests.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada — Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
updated_at=CURRENT_TIMESTAMP WHERE slug='what-to-study-canadian-citizenship-test';
